def ensure_env(content_hash: str, contract: dict[str, Any]) -> dict[str, Any]:
    deps = list(contract.get("dependencies", {}).get("pip", []))
    if not deps:
        return {"ok": True, "python": "/opt/optiplex-lab/venv/bin/python", "dependency_count": 0, "env": None, "installed": False}
    env_dir = ENVS / content_hash
    marker = env_dir / ".forge-ready.json"
    if marker.exists():
        try:
            meta = json.loads(marker.read_text())
            if meta.get("dependencies_hash") == sha_json(deps):
                return {"ok": True, "python": str(env_dir / "bin/python"), "dependency_count": len(deps), "env": str(env_dir), "installed": False}
        except Exception:
            pass
    if env_dir.exists():
        shutil.rmtree(env_dir)
    started = time.monotonic()
    try:
        venv.EnvBuilder(with_pip=True, clear=True).create(env_dir)
        p = subprocess.run([str(env_dir / "bin/python"), "-m", "pip", "install", "--disable-pip-version-check", "--no-input", *deps], capture_output=True, text=True, timeout=180, check=False)
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "dependency install timeout", "dependency_count": len(deps), "duration_ms": round((time.monotonic()-started)*1000, 2)}
    if p.returncode != 0:
        shutil.rmtree(env_dir, ignore_errors=True)
        return {"ok": False, "error": "dependency install failed", "dependency_count": len(deps), "stderr_preview": p.stderr[-1500:], "duration_ms": round((time.monotonic()-started)*1000, 2)}
    meta = {"dependencies_hash": sha_json(deps), "dependencies": deps, "ready_at": utc()}
    safe_write_json(marker, meta)
    return {"ok": True, "python": str(env_dir / "bin/python"), "dependency_count": len(deps), "env": str(env_dir), "installed": True, "duration_ms"

def execute(task: dict[str,Any], input_value: Any, *, context: str="gen6 experience loop") -> dict[str,Any]:
    memory,regression,forge=_mods(); decision=plan(task)
    if decision["action"]=="FORGE_REQUIRED": return {**decision,"executed":False,"ok":False}
    h=str(decision["capability_hash"]); result=forge.invoke_raw(h,input_value,real_task=True,context=context)
    procedure={"capability_hash":h,"capability_name":(_forge_record(forge,h) or {}).get("name"),"evaluator_hash":(_forge_record(forge,h) or {}).get("evaluator_hash")}
    episode=memory.record_episode({**task,"input":input_value},procedure,bool(result.get("ok")),evidence={"run_id":result.get("run_id"),"result_hash":memory.sha_json({k:v for k,v in result.items() if k not in {"output","stdout_preview","stderr_preview"}})},source="experience-loop")
    if decision.get("memory"):
        memory.record_retrieval_outcome(decision["memory"]["memory_hash"],bool(result.get("ok")),episode["episode_id"])
    return {**decision,"executed":True,"ok":bool(result.get("ok")),"result":result,"episode_id":episode["episode_id"],"episode_hash":episode["episode_hash"]}

