def load(name: str, path: pathlib.Path):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f'cannot load {path}')
    module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module); return module

def _build_state_event() -> dict[str, Any] | None:
    if not BUILD_FILE.is_file():
        return None
    raw = BUILD_FILE.read_text(encoding="utf-8", errors="replace")
    try:
        rec = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if not isinstance(rec, dict):
        return None
    data = sanitize({"tool": "build_state", "event": "accepted_build_state", **rec})
    line_sha = sha_bytes(raw.encode())
    return {
        "id": "ev:" + sha_bytes(f"{BUILD_FILE}:{line_sha}".encode())[:24],
        "source_path": str(BUILD_FILE),
        "source_line": 1,
        "evidence_line_sha256": line_sha,
        "timestamp": str(data.get("accepted_at") or data.get("installed_at") or ""),
        "data": data,
    }

def plan(task: dict[str,Any]) -> dict[str,Any]:
    memory,regression,forge=_mods()
    retrieval=memory.retrieve(task)
    regression_hints=regression.search({"desired_name":task.get("desired_name") or task.get("capability_name"),"tags":task.get("tags") or task.get("applicability") or []})
    selected=retrieval.get("selected")
    if selected:
        proc=selected.get("procedure") or {}; h=proc.get("capability_hash"); rec=_forge_record(forge,h) if h else None
        if h and rec and rec.get("state") not in {"REJECTED","EXPIRED","SUPERSEDED"} and pathlib.Path(str(rec.get("object") or "")).exists():
            return {"action":"MEMORY_REUSE","memory":selected,"regressions":regression_hints,"capability_hash":h,"forge_gap_opened":False,"reason":"applicable active memory points to an available authoritative capability"}
    gap={"desired_name":task.get("desired_name") or task.get("capability_name") or "","purpose":task.get("intent") or task.get("purpose") or "","applicability":task.get("tags") or task.get("applicability") or []}
    matches=forge.search(gap)
    if matches and ("exact_name" in matches[0].get("reasons",[]) or float(matches[0].get("tag_overlap",0))>=0.75):
        return {"action":"FORGE_REUSE","memory":None,"regressions":regression_hints,"capability_hash":matches[0]["content_hash"],"forge_gap_opened":False,"forge_matches":matches[:5],"reason":"no applicable memory; Forge registry has an existing applicable capability"}
    return {"action":"FORGE_REQUIRED","memory":None,"regressions":regression_hints,"capability_hash":None,"forge_gap_opened":False,"forge_matches":matches[:5],"reason":"no applicable memory or existing Forge capability; invention is genuinely required"}

def compile_capability_failure(failed_hash:str,*,known_good_hash:str|None=None,case_name:str|None=None,lineage_name:str|None=None)->dict[str,Any]:
    caps=_forge_registry(); bad=caps.get(failed_hash)
    if not isinstance(bad,dict): raise RegressionError(f"failed capability not found: {failed_hash}")
    bad_obj=pathlib.Path(str(bad.get("object") or "")); contract_path=bad_obj/"capability.json"
    if not contract_path.exists():
        fixture={"fixture_type":"nonreplayable","selector":{"name":lineage_name or bad.get("name")},"known_bad_hash":failed_hash,"known_good_hash":known_good_hash,"failure_evidence":{"reason":"capability object unavailable","state":bad.get("state"),"evaluator_hash":bad.get("evaluator_hash")},"uncertainty":"No immutable capability object remains; retained as candidate evidence only."}
        h,_=_store_fixture(fixture,"CANDIDATE"); return {"ok":True,"regression_hash":h,"state":"CANDIDATE","reason":"nonreplayable"}
    contract=json.loads(contract_path.read_text())
    case=_evaluation_failure_case(bad,contract,case_name)
    if not case:
        fixture={"fixture_type":"nonreplayable","selector":{"name":lineage_name or bad.get("name")},"known_bad_hash":failed_hash,"known_good_hash":known_good_hash,"failure_evidence":{"reason":"no evaluation case available","state":bad.get("state"),"evaluator_hash":bad.get("evaluator_hash")},"uncertainty":"Failure cannot be converted to an executable oracle automatically."}
        h,_=_store_fixture(fixture,"CANDIDATE"); return {"ok":True,"regression_hash":h,"state":"CANDIDATE","reason":"no-case"}
    oracle={"expect_error":True} if case.get("expect_error") is True else {"expected":case.get("expected")}
    fixture={"fixture_type":"capability_io","selector":{"name":lineage_name or bad.get("name")},"input":case.
